import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import re

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'bmp', 'tiff', 'webp']

os.makedirs(UPLOAD_DIR, exist_ok=True)

def validate_filename(filename):
    """Sanitize filename to prevent directory traversal"""
    name = secure_filename(filename)
    if not name:
        return None
    return name

def get_output_path(input_name, target_format):
    base = os.path.splitext(input_name)[0]
    file_hash = hashlib.md5(input_name.encode()).hexdigest()[:8]
    return os.path.join(UPLOAD_DIR, f"{base}_{file_hash}.{target_format}")

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.4.1"})

@app.route('/api/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to target format using ImageMagick"""
    if 'file' not in request.files:
        return jsonify({"error": "no file provided"}), 400

    file = request.files['file']
    target_format = request.form.get('format', 'png').lower().strip()
    resize_spec = request.form.get('resize', '')
    quality = request.form.get('quality', '85')

    # Validate target format
    if target_format not in ALLOWED_FORMATS:
        return jsonify({"error": f"unsupported format: {target_format}"}), 400

    # Validate quality is numeric
    if not quality.isdigit() or int(quality) < 1 or int(quality) > 100:
        return jsonify({"error": "quality must be 1-100"}), 400

    # Validate filename
    safe_name = validate_filename(file.filename)
    if not safe_name:
        return jsonify({"error": "invalid filename"}), 400

    # Save uploaded file
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    file.save(input_path)
    output_path = get_output_path(safe_name, target_format)

    # Build ImageMagick command
    cmd_parts = ['convert', input_path]

    # Apply resize if specified
    if resize_spec:
        # Validate resize spec format (e.g., "800x600", "50%")
        if not re.match(r'^[0-9]+x[0-9]+$|^[0-9]+%$', resize_spec):
            os.unlink(input_path)
            return jsonify({"error": "invalid resize spec"}), 400
        cmd_parts.extend(['-resize', resize_spec])

    cmd_parts.extend(['-quality', quality, output_path])

    # Execute conversion
    try:
        result = subprocess.run(
            ' '.join(cmd_parts),
            shell=True,
            capture_output=True,
            timeout=30
        )
        if result.returncode != 0:
            os.unlink(input_path)
            return jsonify({"error": "conversion failed", "detail": result.stderr.decode()[:200]}), 500
    except subprocess.TimeoutExpired:
        os.unlink(input_path)
        return jsonify({"error": "conversion timeout"}), 504

    # Cleanup input
    os.unlink(input_path)

    return send_file(output_path, as_attachment=True,
                     download_name=f"converted.{target_format}")

@app.route('/api/metadata', methods=['POST'])
def get_metadata():
    """Extract image metadata using identify command"""
    if 'file' not in request.files:
        return jsonify({"error": "no file provided"}), 400

    file = request.files['file']
    safe_name = validate_filename(file.filename)
    if not safe_name:
        return jsonify({"error": "invalid filename"}), 400

    input_path = os.path.join(UPLOAD_DIR, safe_name)
    file.save(input_path)

    try:
        result = subprocess.run(
            ['identify', '-verbose', input_path],
            capture_output=True,
            timeout=10
        )
        os.unlink(input_path)
        return jsonify({"metadata": result.stdout.decode()[:5000]})
    except Exception as e:
        if os.path.exists(input_path):
            os.unlink(input_path)
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
